"""Strategy interface for the backtesting framework.

Contract: a strategy sees only data delivered to on_bar. Anything else is a
look-ahead bug by definition — the engine's capped data view enforces it.
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass


@dataclass(frozen=True)
class Bar:
    date: str
    open: float
    high: float
    low: float
    close: float
    volume: int


@dataclass(frozen=True)
class Signal:
    """Desired portfolio weight AFTER the current bar (executed next bar)."""

    date: str
    target_weight: float    # clipped by the engine to the configured range


class Strategy(ABC):
    """Subclass this and implement on_bar."""

    @abstractmethod
    def on_bar(self, bar: Bar, position_weight: float) -> Signal:
        """Called once per bar, after the close, with the current weight."""

    @property
    def name(self) -> str:
        return self.__class__.__name__


class BuyAndHold(Strategy):
    """Reference strategy: enter long on the first bar, then hold."""

    def __init__(self, weight: float = 1.0) -> None:
        self._weight = weight

    def on_bar(self, bar: Bar, position_weight: float) -> Signal:
        return Signal(bar.date, self._weight)

"""Contract tests for the Strategy interface (starter)."""

import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)

from backtest.strategy import Bar, BuyAndHold, Signal, Strategy  # noqa: E402


def test_buy_and_hold_targets_full_weight():
    bar = Bar("2024-01-02", 10.0, 10.5, 9.9, 10.2, 1000)
    sig = BuyAndHold().on_bar(bar, 0.0)
    assert isinstance(sig, Signal)
    assert sig.target_weight == 1.0


def test_strategy_is_abstract():
    try:
        Strategy()  # abstract: instantiation must fail
    except TypeError:
        return
    raise AssertionError("Strategy must be abstract (on_bar unimplemented)")


def main() -> int:
    failed = 0
    for test in (test_buy_and_hold_targets_full_weight, test_strategy_is_abstract):
        try:
            test()
            print(f"PASS {test.__name__}")
        except AssertionError as exc:
            failed += 1
            print(f"FAIL {test.__name__}: {exc}")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
